return {
    -- VillageHead [8273]
    ["STR_ID_VillageHead[8273][Text1]"] = "Phoenix Castle is always our friend! My village is in trouble now, I hope our friends in the Castle can help us out! If you are here to help me, I have a bunch of jobs for you to do! Which of the following quests do you want to try?",
    ["STR_ID_VillageHead[8273][Text2]"] = "Phoenix Castle will send help to us? Thank you! Thank you, so much!",
    ["STR_ID_VillageHead[8273][Text3]"] = "You`re welcome! By the way, there`s a Bold Boy who`s going to  kill a Ratling!",
    ["STR_ID_VillageHead[8273][Text4]"] = "@STR_COMMON[26]",
    ["STR_ID_VillageHead[8273][Text5]"] = "I am quite impressed by your performance! You really are great! We could use more people like you in the village.",
    ["STR_ID_VillageHead[8273][Text6]"] = "The Ratlings are out of control! We found that there is an elusive Ratling King, hiding out there. If you killed it, I think the Ratlings would get confused and stop attacking our village. Snake Meat is the favorite food of the Ratling King,",
    ["STR_ID_VillageHead[8273][Text7]"] = "Good Wine! I could smell it as soon as you were walking up the path! Well, let`s get busy making that lure.",
    ["STR_ID_VillageHead[8273][Text8]"] = "You must be thinking what I am doing. I will make a lure using the Snake Meat! To make the lure more attractive! I need some Wine! Could you buy a bottle of wine from Deeler Shen?",
    ["STR_ID_VillageHead[8273][Text9]"] = "@STR_COMMON[434]",
    ["STR_ID_VillageHead[8273][Text10]"] = "I was quite impressed by you performance! Good job!",
    ["STR_ID_VillageHead[8273][Text11]"] = "I will soak the Snake Meet in the Wine, so it will take a bit. Why not use this time to slay some Ratlings! This will help make you smell like the Ratlings. That way, it will make it harder for the Ratling King to discover you!",
    ["STR_ID_VillageHead[8273][Text12]"] = "Good! You have it! Now take a little break. I want study the Frost Token first, and will instruct you on what to do, later.",
    ["STR_ID_VillageHead[8273][Text13]"] = "You still need a Frost Token. It will provide you with extra defense, especially your resistance against heat! I`ll show you where to find it!",
    ["STR_ID_VillageHead[8273][Text14]"] = "@STR_COMMON[434]",
    ["STR_ID_VillageHead[8273][Text15]"] = "I can`t believe my ears! You killed it and saved our village! See? The Ratlings are scattering! Your name will be remembered for as long as our village remains! Thank you, hero!",
    ["STR_ID_VillageHead[8273][Text16]"] = "Listen! The Ratling King excels at fire attacks. This Frost Token can provide with you extra resistance against heat and fire, for 5 minutes. Use the Wine Soaked Snake to charm it out, then slay it while you`re protected. If you don`t make it in time,",
    ["STR_ID_VillageHead[8273][Text17]"] = "@STR_COMMON[434]",
    ["STR_ID_VillageHead[8273][Text18]"] = "Fire Spirits are another big threat to the village! In fact, they`re a threat to Phoenix Castle, too! There are some militiaman fighting desperately against these evil spirits. Maybe you can offer them some help? You can speak with the Militia Captain",
    ["STR_ID_VillageHead[8273][Option1]"] = "I~was~sent~to~help~you!",
    ["STR_ID_VillageHead[8273][Option2]"] = "Ratling~King~1.",
    ["STR_ID_VillageHead[8273][Option3]"] = "Ratling~King~2.",
    ["STR_ID_VillageHead[8273][Option4]"] = "Ratling~King~3.",
    ["STR_ID_VillageHead[8273][Option5]"] = "Ratling~King~4.",
    ["STR_ID_VillageHead[8273][Option6]"] = "Ratling~King~5.",
    ["STR_ID_VillageHead[8273][Option7]"] = "Help~Militia~Captain.",
    ["STR_ID_VillageHead[8273][Option8]"] = "@STR_COMMON[294]",
}
